namespace SiriNative;
internal class ToolWindow : Window
{
 public StackPanel Body {get;}=new(){Margin=new Thickness(24)};
 public ToolWindow(Window owner,string title,int width=680,int height=590){Owner=owner;Style=(Style)Application.Current.FindResource(typeof(Window));Title=title;Width=width;Height=height;MinWidth=420;MinHeight=350;WindowStartupLocation=WindowStartupLocation.CenterOwner;Content=new ScrollViewer{Content=Body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
}
internal static class Ui
{
 public static TextBlock Label(string text)=>new(){Text=text,TextWrapping=TextWrapping.Wrap,Foreground=new SolidColorBrush(Color.FromRgb(159,180,198)),Margin=new Thickness(0,7,0,8),FontSize=12};
 public static TextBox Field(StackPanel body,string label,string value="",bool multiline=false){body.Children.Add(Label(label));var input=new TextBox{Text=value,TextWrapping=TextWrapping.Wrap,AcceptsReturn=multiline,MinHeight=multiline?145:32,MaxHeight=multiline?300:40,VerticalScrollBarVisibility=multiline?ScrollBarVisibility.Auto:ScrollBarVisibility.Disabled,Margin=new Thickness(0,0,0,11)};body.Children.Add(input);return input;}
 public static Button Button(string title,Action action){var button=new Button{Content=title,Margin=new Thickness(0,6,8,8)};button.Click+=(_,_)=>{try{action();}catch(Exception e){MessageBox.Show(e.Message,title);}};return button;}
 public static Button Async(string title,Func<Task> action){var button=new Button{Content=title,Margin=new Thickness(0,6,8,8)};button.Click+=async(_,_)=>{button.IsEnabled=false;try{await action();}catch(Exception e){MessageBox.Show(e.Message,title);}finally{button.IsEnabled=true;}};return button;}
 public static decimal Number(string text){if(!decimal.TryParse(text,NumberStyles.Number,CultureInfo.InvariantCulture,out var result))throw new ArgumentException("Enter numeric amounts using a decimal point, e.g. 12.50.");return result;}
 public static TextBox Output(StackPanel body){var text=new TextBox{IsReadOnly=true,TextWrapping=TextWrapping.Wrap,AcceptsReturn=true,MinHeight=140,MaxHeight=350,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(0,10,0,12)};body.Children.Add(text);return text;}
}
internal static class Tools
{
 public static void Read(MainWindow app,string title,string body){var window=new ToolWindow(app,title,760,650);var text=Ui.Output(window.Body);text.Text=body;text.MinHeight=350;window.Body.Children.Add(Ui.Button("Copy selected text / all",()=>Clipboard.SetText(text.SelectedText.Length>0?text.SelectedText:body)));window.Show();}
 public static void Settings(MainWindow app)
 {
  var window=new ToolWindow(app,"Settings & privacy",650,710);var state=app.Store.Data.Settings;
  window.Body.Children.Add(Ui.Label("Native Windows app · No Electron, Chromium, or local web server is used by this executable."));
  var wake=new CheckBox{Content="Listen for ‘Hey Siri’ while this app is running",IsChecked=app.Speech.Requested};window.Body.Children.Add(wake);window.Body.Children.Add(Ui.Label("Opt-in microphone use. The phrase is recognized locally with an installed English Windows recognizer. No audio is saved. Closing the app stops listening; each launch starts with voice activation off. Windows microphone permissions/policy can block it."));
  var shortcut=new CheckBox{Content="Ctrl + Shift + Space opens separate Writing Tools",IsChecked=app.ShortcutEnabled};window.Body.Children.Add(shortcut);
  var memory=new CheckBox{Content="Save conversations on this device",IsChecked=state.Memory};window.Body.Children.Add(memory);
  var language=Ui.Field(window.Body,"Reply language (auto, English, French, Japanese, Korean, Portuguese, Spanish)",state.Language);
  var model=new ComboBox{ItemsSource=new[]{"Automatic"},SelectedIndex=0};window.Body.Children.Add(Ui.Label("Local text model"));window.Body.Children.Add(model);var vision=new ComboBox{ItemsSource=new[]{"Automatic"},SelectedIndex=0};window.Body.Children.Add(Ui.Label("Local image model"));window.Body.Children.Add(vision);
  window.Body.Children.Add(Ui.Async("Refresh installed models",async()=>{var names=await app.Ai.Models();var values=new[]{"Automatic"}.Concat(names).ToArray();model.ItemsSource=values;vision.ItemsSource=values;model.SelectedItem=names.Contains(state.Model)?state.Model:"Automatic";vision.SelectedItem=names.Contains(state.VisionModel)?state.VisionModel:"Automatic";}));
  var voice=new ComboBox{ItemsSource=new[]{"Default"}.Concat(app.Speech.Voices()).ToArray(),SelectedItem=state.Voice.Length>0?state.Voice:"Default"};window.Body.Children.Add(Ui.Label("Installed Windows voice"));window.Body.Children.Add(voice);var pace=Ui.Field(window.Body,"Speaking pace (-5 to 5)",state.SpeechRate.ToString(CultureInfo.InvariantCulture));
  var excluded=Ui.Field(window.Body,"Excluded context apps (comma-separated, e.g. Outlook, Chrome, Edge, Word)",string.Join(", ",state.ExcludedApps));window.Body.Children.Add(Ui.Label("Exclusions are checked before native app reads. A screenshot or text you paste can still contain excluded content; review before sharing. Saved data is plaintext under "+app.Store.Folder));
  window.Body.Children.Add(Ui.Button("Delete saved conversation memory",()=>{if(app.Confirm("Delete memory?","Delete saved conversations, but not notes, reminders or meals?")){app.Store.Data.Conversations.Clear();app.Store.Save();app.RefreshConversationList();}}));
  window.Body.Children.Add(Ui.Button("Save settings",()=>{
   var languages=new[]{"auto","English","French","Japanese","Korean","Portuguese","Spanish"};if(!languages.Contains(language.Text.Trim(),StringComparer.OrdinalIgnoreCase))throw new ArgumentException("Choose one of the listed reply languages.");if(!int.TryParse(pace.Text,out var rate)||rate< -5||rate>5)throw new ArgumentException("Speaking pace must be -5 to 5.");
   if(wake.IsChecked==true&&!app.Speech.Requested){if(!app.Confirm("Enable microphone listening?","While Siri is running, your microphone will listen locally for ‘Hey Siri’. It will not save audio. Closing the app stops it. Enable?"))return;app.Speech.StartWake();}else if(wake.IsChecked!=true)app.Speech.StopWake();app.UpdateWake();
   if(!app.SetWritingShortcut(shortcut.IsChecked==true))throw new InvalidOperationException("The writing shortcut is already in use. Voice settings were applied, but the shortcut was not registered.");
   state.Memory=memory.IsChecked==true;state.Language=language.Text.Trim();state.SpeechRate=rate;state.Voice=voice.SelectedItem is string v&&v!="Default"?v:"";
   // Do not clear an existing choice unless the user explicitly changed a populated selector.
   if(model.Items.Count>1)state.Model=model.SelectedItem is string m&&m!="Automatic"?m:"";if(vision.Items.Count>1)state.VisionModel=vision.SelectedItem is string im&&im!="Automatic"?im:"";
   state.ExcludedApps=excluded.Text.Split(',').Select(x=>x.Trim()).Where(x=>x.Length>0).Distinct(StringComparer.OrdinalIgnoreCase).ToList();app.Store.Save();window.Close();_ = app.RefreshModels();
  }));window.ShowDialog();
 }
 public static void Library(MainWindow app,string title,List<Entry> entries,bool reminder=false)
 {
  var window=new ToolWindow(app,title,760,650);var search=Ui.Field(window.Body,"Search title or content");var list=new ListBox{Height=220,Background=new SolidColorBrush(Color.FromRgb(22,32,43)),Foreground=Brushes.White};window.Body.Children.Add(list);var preview=Ui.Output(window.Body);preview.MinHeight=90;
  void Refresh(){list.ItemsSource=entries.Where(x=>(x.Title+" "+x.Body).Contains(search.Text,StringComparison.OrdinalIgnoreCase)).OrderByDescending(x=>x.Pinned).ThenBy(x=>x.Done).ThenBy(x=>x.Due??DateTimeOffset.MaxValue).ThenByDescending(x=>x.Updated).ToList();}
  search.TextChanged+=(_,_)=>Refresh();list.SelectionChanged+=(_,_)=>preview.Text=list.SelectedItem is Entry entry?entry.Body:"";var buttons=new WrapPanel();window.Body.Children.Add(buttons);
  buttons.Children.Add(Ui.Button("New",()=>{EditEntry(app,entries,new(),reminder);Refresh();}));buttons.Children.Add(Ui.Button("Edit",()=>{if(list.SelectedItem is Entry entry){EditEntry(app,entries,entry,reminder);Refresh();}}));buttons.Children.Add(Ui.Button("Pin / unpin",()=>{if(list.SelectedItem is Entry entry){entry.Pinned=!entry.Pinned;app.Store.Save();Refresh();}}));
  if(reminder){buttons.Children.Add(Ui.Button("Complete / reopen",()=>{if(list.SelectedItem is Entry entry){entry.Done=!entry.Done;app.Store.Save();Refresh();}}));buttons.Children.Add(Ui.Button("Snooze 1 hour",()=>{if(list.SelectedItem is Entry entry){entry.Done=false;entry.Due=DateTimeOffset.Now.AddHours(1);app.Store.Save();Refresh();}}));window.Body.Children.Add(Ui.Label("Due reminders appear in Siri’s status area while the app is open. No background alarm runs after the app closes."));}
  else{buttons.Children.Add(Ui.Button("Use as context",()=>{if(list.SelectedItem is Entry entry){app.AddSources(new[]{new Source{Title=entry.Title,Text=entry.Body}});window.Close();}}));buttons.Children.Add(Ui.Button("Export text",()=>{if(list.SelectedItem is Entry entry){var dialog=new SaveFileDialog{Filter="Text note|*.txt",FileName="Siri note.txt"};if(dialog.ShowDialog(window)==true)File.WriteAllText(dialog.FileName,entry.Title+"\n\n"+entry.Body);}}));}
  buttons.Children.Add(Ui.Button("Delete",()=>{if(list.SelectedItem is Entry entry&&app.Confirm("Delete entry?","Delete this entry permanently?")){entries.Remove(entry);app.Store.Save();Refresh();}}));Refresh();window.ShowDialog();
 }
 public static void EditEntry(MainWindow app,List<Entry> entries,Entry original,bool reminder)
 {
  var window=new ToolWindow(app,reminder?"Reminder":"Edit saved text",650,590);var title=Ui.Field(window.Body,"Title",original.Title);var body=Ui.Field(window.Body,"Content",original.Body,true);TextBox? due=reminder?Ui.Field(window.Body,"Due date and local time",(original.Due??DateTimeOffset.Now.AddHours(1)).ToLocalTime().ToString("yyyy-MM-dd HH:mm")):null;
  window.Body.Children.Add(Ui.Button("Save",()=>{var entry=new Entry{Id=original.Id,Title=title.Text.Trim(),Body=body.Text,Done=original.Done,Pinned=original.Pinned};Rules.ValidateEntry(entry);if(reminder){if(!DateTimeOffset.TryParse(due!.Text,CultureInfo.CurrentCulture,DateTimeStyles.AssumeLocal,out var date))throw new ArgumentException("Enter a valid local date and time.");entry.Due=date;}if(entries.Count>=1000&&!entries.Any(x=>x.Id==entry.Id))throw new InvalidOperationException("This library is limited to 1,000 entries.");entries.RemoveAll(x=>x.Id==entry.Id);entries.Add(entry);app.Store.Save();window.Close();}));window.ShowDialog();
 }
 public static void Browser(MainWindow app)
 {
  var windows=WindowsIntegration.Browsers(app.Store.Data.Settings);if(windows.Count==0)throw new InvalidOperationException("Open Chrome or Edge, or check exclusions.");var window=new ToolWindow(app,"Read a browser page",700,480);window.Body.Children.Add(Ui.Label("Choose a visible Chrome or Edge window. Only accessible page text is read once. No extension, debugging port or background scan."));var list=new ListBox{ItemsSource=windows,Height=230};window.Body.Children.Add(list);window.Body.Children.Add(Ui.Async("Share chosen page text",async()=>{if(list.SelectedItem is not AppWindow selected)return;if(!app.Confirm("Share browser context?",selected.Title+"\nRead accessible text from this window once?"))return;var source=await Task.Run(()=>WindowsIntegration.Browser(selected,app.Store.Data.Settings));app.AddSources(new[]{source});window.Close();}));window.ShowDialog();
 }
 public static void Inbox(MainWindow app)
 {
  var window=new ToolWindow(app,"Search classic Outlook",700,570);window.Body.Children.Add(Ui.Label("Requires currently running classic Outlook; New Outlook is not supported. Searches at most 500 recent default-inbox messages and returns at most twelve excerpts. No mail is edited or sent."));var query=Ui.Field(window.Body,"Search phrase");var output=Ui.Output(window.Body);List<Source> results=new();window.Body.Children.Add(Ui.Async("Search inbox",async()=>{if(!app.Confirm("Read inbox?","Search classic Outlook for: "+query.Text))return;output.Text="Searching…";var phrase=query.Text;results=await Task.Run(()=>WindowsIntegration.Inbox(phrase,app.Store.Data.Settings));output.Text=results.Count+" matches\n\n"+string.Join("\n\n",results.Select(x=>x.Title+"\n"+x.Text));}));window.Body.Children.Add(Ui.Button("Attach results for a question",()=>{if(results.Count==0)throw new InvalidOperationException("Search for matching messages first.");app.AddSources(results);window.Close();}));window.ShowDialog();
 }
 public static void History(MainWindow app)
 {
  var window=new ToolWindow(app,"Search Chrome / Edge history",700,600);var browser=new ComboBox{ItemsSource=new[]{"Chrome","Edge"},SelectedIndex=0};window.Body.Children.Add(browser);var profile=Ui.Field(window.Body,"Profile (Default or Profile N)","Default");var query=Ui.Field(window.Body,"Search phrase");var output=Ui.Output(window.Body);List<Source> results=new();window.Body.Children.Add(Ui.Async("Search approved history snapshot",async()=>{var name=(string)browser.SelectedItem;if(!app.Confirm("Read browser history?","Read a temporary copy of "+name+" / "+profile.Text+" history? It is deleted afterward. No incognito data is available."))return;var chosenProfile=profile.Text;var phrase=query.Text;results=await Task.Run(()=>WindowsIntegration.History(name,chosenProfile,phrase,app.Store.Data.Settings));output.Text=results.Count+" matches\n\n"+string.Join("\n",results.Select(x=>x.Title+"\n"+x.Text));}));window.Body.Children.Add(Ui.Button("Attach results",()=>{if(results.Count==0)throw new InvalidOperationException("No results to attach.");app.AddSources(new[]{new Source{App=results[0].App,Title="Approved browser history",Text=string.Join("\n",results.Select(x=>x.Title+"\n"+x.Text))}});window.Close();}));window.ShowDialog();
 }
 public static void Folder(MainWindow app)
 {
  using var picker=new System.Windows.Forms.FolderBrowserDialog{Description="Choose a folder to search once"};if(picker.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;var root=picker.SelectedPath;var window=new ToolWindow(app,"Search selected text files",700,570);window.Body.Children.Add(Ui.Label(root+"\nBounded keyword search, not device-wide semantic indexing. Symlink/reparse directories are skipped."));var query=Ui.Field(window.Body,"Search words");var output=Ui.Output(window.Body);List<Source> results=new();window.Body.Children.Add(Ui.Async("Search folder",async()=>{if(string.IsNullOrWhiteSpace(query.Text))throw new ArgumentException("Enter search words.");var terms=query.Text.Split(' ',StringSplitOptions.RemoveEmptyEntries);results=await Task.Run(()=>{var found=new List<Source>();var pending=new Stack<string>();pending.Push(root);int visited=0,files=0;long read=0;while(pending.Count>0&&visited++<3000&&files<3000&&read<32*1024*1024&&found.Count<12){var dir=pending.Pop();try{if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)continue;foreach(var sub in Directory.EnumerateDirectories(dir))pending.Push(sub);foreach(var file in Directory.EnumerateFiles(dir)){if(++files>3000)break;if(!new[]{".txt",".md",".eml",".csv",".json",".log",".ics",".html"}.Contains(Path.GetExtension(file).ToLowerInvariant()))continue;var info=new FileInfo(file);if(info.Length>512*1024)continue;read+=info.Length;if(read>32*1024*1024)break;var text=File.ReadAllText(file);var match=terms.Select(term=>text.IndexOf(term,StringComparison.OrdinalIgnoreCase)).FirstOrDefault(i=>i>=0,-1);if(match<0)continue;int start=Math.Max(0,match-160);found.Add(new(){Title=file,Text=text.Substring(start,Math.Min(1400,text.Length-start))});if(found.Count>=12)break;}}catch(IOException){}catch(UnauthorizedAccessException){}}return found;});output.Text=results.Count+" matches\n\n"+string.Join("\n\n",results.Select(x=>x.Title+"\n"+x.Text));}));window.Body.Children.Add(Ui.Button("Attach excerpts",()=>{app.AddSources(results);window.Close();}));window.ShowDialog();
 }
 public static async void Screenshot(MainWindow app)
 {
  if(!app.Confirm("Capture one screen image?","This captures your primary display, including any private or excluded app content that is visible. You can review it before attaching. Nothing is sent automatically."))return;
  try{app.Hide();await Task.Delay(350);var screen=System.Windows.Forms.Screen.PrimaryScreen??throw new InvalidOperationException("No display available.");var bounds=screen.Bounds;using var bitmap=new System.Drawing.Bitmap(bounds.Width,bounds.Height);using(var graphics=System.Drawing.Graphics.FromImage(bitmap))graphics.CopyFromScreen(bounds.Location,System.Drawing.Point.Empty,bounds.Size);using var stream=new MemoryStream();bitmap.Save(stream,System.Drawing.Imaging.ImageFormat.Png);var bytes=stream.ToArray();app.Show();app.Activate();var window=new ToolWindow(app,"Review screenshot before attaching",850,640);var preview=new BitmapImage();preview.BeginInit();preview.StreamSource=new MemoryStream(bytes);preview.CacheOption=BitmapCacheOption.OnLoad;preview.EndInit();preview.Freeze();window.Body.Children.Add(new Image{Source=preview,MaxHeight=460,Stretch=Stretch.Uniform});window.Body.Children.Add(Ui.Button("Attach this image",()=>{app.AttachPng(bytes);window.Close();}));window.ShowDialog();}catch(Exception error){app.Show();MessageBox.Show(app,error.Message,"Screenshot");}
 }
 public static void Bill(MainWindow app)
 {
  var window=new ToolWindow(app,"Itemized bill split",740,700);var names=Ui.Field(window.Body,"Diners, separated by commas","Alex, Sam");var lines=Ui.Field(window.Body,"One line per item: label | amount | diner names (decimal point for money)","Pizza | 19.99 | Alex, Sam",true);var tax=Ui.Field(window.Body,"Tax amount","0");var tip=Ui.Field(window.Body,"Tip percentage before tax","18");var output=Ui.Output(window.Body);void Calculate(){try{var diners=names.Text.Split(',').Select(x=>x.Trim()).Where(x=>x.Length>0).ToArray();var items=lines.Text.Split('\n',StringSplitOptions.RemoveEmptyEntries).Select(line=>{var columns=line.Split('|');if(columns.Length!=3)throw new ArgumentException("Use: label | amount | diner names");var owners=columns[2].Split(',').Select(x=>Array.FindIndex(diners,n=>n.Equals(x.Trim(),StringComparison.OrdinalIgnoreCase))).ToArray();return new BillItem(Ui.Number(columns[1]),owners);}).ToList();var shares=Rules.Split(diners,items,Ui.Number(tax.Text),Ui.Number(tip.Text));output.Text="Total: $"+(shares.Sum(x=>x.Total)/100m).ToString("F2")+"\n\n"+string.Join("\n",shares.Select(x=>x.Name+": $"+(x.Total/100m).ToString("F2")+" (items $"+(x.Items/100m).ToString("F2")+", tax $"+(x.Tax/100m).ToString("F2")+", tip $"+(x.Tip/100m).ToString("F2")+")"));}catch(Exception e){output.Text=e.Message;}}
  foreach(var field in new[]{names,lines,tax,tip})field.TextChanged+=(_,_)=>Calculate();window.Body.Children.Add(Ui.Button("Copy reviewed split",()=>Clipboard.SetText(output.Text)));window.Body.Children.Add(Ui.Button("Review a payment in Venmo",()=>Payment(app)));window.Body.Children.Add(Ui.Label("No transfer is sent or verified by Siri. Tax/tip allocation preserves every cent; shared-item remainder ties follow diner order."));Calculate();window.ShowDialog();
 }
 private static void Payment(MainWindow app){var window=new ToolWindow(app,"Venmo handoff",530,440);var recipient=Ui.Field(window.Body,"Venmo username");var amount=Ui.Field(window.Body,"Amount ($)");var note=Ui.Field(window.Body,"Note","Bill split");window.Body.Children.Add(Ui.Button("Continue externally",()=>{var url=Rules.Venmo(recipient.Text,Ui.Number(amount.Text),note.Text);if(app.Confirm("Open Venmo?","Review this payment in Venmo. You must sign in and confirm there. Siri cannot submit, verify, or undo a payment. Apple Cash is not integrated."))WindowsIntegration.Open(url.AbsoluteUri);}));window.ShowDialog();}
 public static void Meals(MainWindow app){var window=new ToolWindow(app,"Nutrition journal",680,520);var list=new ListBox{Height=280,ItemsSource=app.Store.Data.Meals.ToList()};window.Body.Children.Add(list);void Refresh()=>list.ItemsSource=app.Store.Data.Meals.ToList();window.Body.Children.Add(Ui.Button("Add reviewed meal",()=>{EditMeal(app,new());Refresh();}));window.Body.Children.Add(Ui.Button("Edit selected",()=>{if(list.SelectedItem is Meal meal){EditMeal(app,meal);Refresh();}}));window.Body.Children.Add(Ui.Button("Delete selected",()=>{if(list.SelectedItem is Meal meal&&app.Confirm("Delete meal?",meal.Name)){app.Store.Data.Meals.Remove(meal);app.Store.Save();Refresh();}}));window.ShowDialog();}
 public static void MealFromAnswer(MainWindow app,string answer){var clean=answer.Trim();if(clean.StartsWith("```")){var newline=clean.IndexOf('\n');clean=newline>=0?clean[(newline+1)..].TrimEnd('`','\r','\n',' '):clean;}var meal=JsonSerializer.Deserialize<Meal>(clean,Store.Json)??throw new ArgumentException("No meal JSON found. Ask for name and items with calories/protein/carbs/fat, then review the result.");EditMeal(app,meal);}
 private static void EditMeal(MainWindow app,Meal original){var window=new ToolWindow(app,"Review nutrition estimates",700,620);var name=Ui.Field(window.Body,"Meal name",original.Name);var rows=Ui.Field(window.Body,"One line per food: name | calories | protein g | carbs g | fat g",string.Join("\n",original.Items.Select(x=>$"{x.Name} | {x.Calories.ToString(CultureInfo.InvariantCulture)} | {x.Protein.ToString(CultureInfo.InvariantCulture)} | {x.Carbs.ToString(CultureInfo.InvariantCulture)} | {x.Fat.ToString(CultureInfo.InvariantCulture)}")),true);var totals=Ui.Label("");window.Body.Children.Add(totals);List<Food> Parse(){var foods=rows.Text.Split('\n',StringSplitOptions.RemoveEmptyEntries).Select(line=>{var c=line.Split('|');if(c.Length!=5||string.IsNullOrWhiteSpace(c[0]))throw new ArgumentException("Use five columns per food.");var numbers=c.Skip(1).Select(Ui.Number).ToArray();if(numbers.Any(x=>x<0||x>100000))throw new ArgumentException("Enter non-negative nutrition values under 100,000.");return new Food{Name=c[0].Trim(),Calories=numbers[0],Protein=numbers[1],Carbs=numbers[2],Fat=numbers[3]};}).ToList();if(foods.Count<1||foods.Count>50)throw new ArgumentException("Add 1–50 foods.");return foods;}rows.TextChanged+=(_,_)=>{try{var foods=Parse();totals.Text=$"{foods.Sum(x=>x.Calories):0} kcal · {foods.Sum(x=>x.Protein):0.0}g protein · {foods.Sum(x=>x.Carbs):0.0}g carbs · {foods.Sum(x=>x.Fat):0.0}g fat";}catch(Exception e){totals.Text=e.Message;}};window.Body.Children.Add(Ui.Label("Review portions and every estimate. This is not medical advice and is not connected to a health account. Saving is explicit."));window.Body.Children.Add(Ui.Button("Save reviewed meal",()=>{var meal=new Meal{Id=original.Id,At=original.At,Name=name.Text.Trim(),Items=Parse()};if(meal.Name.Length==0||meal.Name.Length>200)throw new ArgumentException("Add a name under 200 characters.");app.Store.Data.Meals.RemoveAll(x=>x.Id==meal.Id);app.Store.Data.Meals.Add(meal);app.Store.Save();window.Close();}));window.ShowDialog();}
}
